pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity as f64;
    let before = bin_residual as f64;
    let post = post_residual as f64;

    // Base scaling
    let base = cap / 15.0; // tighter scaling for tighter bins

    // ---------- 1. Residual shape ----------
    let resid_ratio = post / cap;
    let mut score = base * (1.0 - resid_ratio.powi(2));

    // Tight residual bonus / penalty
    if resid_ratio < 0.01 {
        score -= base * 0.8;
    } else if resid_ratio < 0.04 {
        score -= base * 0.4;
    } else if resid_ratio > 0.10 {
        score += base * 0.3;
    }

    // ---------- 2. Next‑item lookahead ----------
    if next_item_size > 0 {
        if next_item_size as f64 <= post {
            // next will fit
            score -= base * 0.1;
        } else {
            let diff = next_item_size as i32 - post as i32;
            if diff > 0 {
                // next won't fit – quadratic penalty
                score += (diff as f64).powi(2) * (base / 200.0);
            }
        }
    }

    // ---------- 3. Progress adjustment ----------
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.25 {
        if resid_ratio < 0.07 {
            score -= base * 0.04;
        }
    } else if progress > 0.85 {
        if resid_ratio > 0.06 {
            score += (resid_ratio - 0.06) * base * 2.5;
        }
    }

    // ---------- 4. Mean residual comparison ----------
    if post > mean_residual {
        let diff = post - mean_residual;
        score += diff * (base / cap) * 0.5;
    }

    // ---------- 5. Open bins penalty ----------
    let open_threshold = (total_items as f64 * 0.08).ceil() as usize;
    if open_bins_count > open_threshold {
        let excess = open_bins_count as f64 - open_threshold as f64;
        score += excess * (base / 25.0);
    }

    // ---------- 6. Fitting bins crowding ----------
    if fitting_bins_count == 1 {
        score -= base * 1.2;
    } else if fitting_bins_count > 8 {
        score += base * 0.8;
    } else {
        // moderate crowding bonus
        score -= base * 0.2 * (fitting_bins_count as f64 / 5.0).min(1.0);
    }

    // ---------- 7. New‑bin candidate handling ----------
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // existing bin available – discourage new
            score += base * 1.5;
        } else {
            // no fit – reward opening a new bin
            score -= base * 1.5;
        }
        // extra factor if many open bins
        if open_bins_count > 5 {
            score -= base * 0.5;
        }
    }

    // ---------- 8. Modulo tweak ----------
    let mod3 = post_residual % 3;
    if mod3 == 0 {
        score -= base * 0.5;
    } else if mod3 == 1 {
        score -= base * 0.3;
    } else {
        score += base * 0.15;
    }

    // ---------- 9. Dead‑space ratio ----------
    let consumed = before - post;
    if consumed > 0.0 {
        let consume_ratio = consumed / before;
        if consume_ratio > 0.90 {
            score -= base * 0.25;
        } else if consume_ratio < 0.10 {
            score += base * 0.12;
        }
    }

    // ---------- 10. Future‑fit bonus ----------
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= base * 0.05;
    }

    // ---------- 11. Late‑phase open‑bin check ----------
