pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base scale derived from capacity
    let cap_f = bin_capacity as f64;
    let old_res = bin_residual as f64;
    let new_res = (bin_residual - item_size) as f64;
    let base = cap_f / 18.0;

    // ---------- 1. Residual tightness ----------
    let mut score = base * (1.0 - (new_res / cap_f).powi(3));

    // ---------- 2. Residual vs mean ----------
    if new_res < mean_residual {
        score -= base * 0.05; // reward tighter than average
    } else if new_res > mean_residual * 1.2 {
        score += base * 0.04; // penalize overly loose
    }

    // Close to mean residual: extra reward
    if (new_res - mean_residual).abs() < cap_f * 0.05 {
        score -= base * 0.10;
    }

    // ---------- 3. Small residual penalty when many open bins ----------
    if new_res < cap_f * 0.10 && open_bins_count > 5 {
        score += base * 0.07;
    }

    // ---------- 4. Next‑item lookahead ----------
    if next_item_size > 0 {
        let diff = next_item_size as f64 - new_res;
        if diff > 0.0 {
            // next item won't fit: quadratic penalty
            score += diff.powi(2) * (base / 80.0);
        } else {
            // next item fits: modest bonus
            score -= base * 0.08;
        }
    }

    // ---------- 5. Progress‑dependent tweak ----------
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.4 {
        if new_res / cap_f < 0.10 {
            score -= base * 0.06;
        }
    } else if progress > 0.85 {
        if new_res / cap_f > 0.07 {
            score += (new_res / cap_f - 0.07) * base * 1.5;
        }
    }

    // ---------- 6. Open‑bins penalty ----------
    if open_bins_count > 6 {
        let excess = open_bins_count as f64 - 6.0;
        score += excess * (base / 25.0);
    }

    // ---------- 7. Unique‑fit reward ----------
    if fitting_bins_count == 1 {
        score -= base * 1.20;
    }

    // ---------- 8. New‑bin candidate handling ----------
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += base * 2.00; // discourage opening a new bin
        } else {
            score -= base * 1.90; // reward opening a new bin
        }
    }

    // ---------- 9. Modulo 7 tweak ----------
    let mod7 = post_residual % 7;
    if mod7 == 0 {
        score -= base * 0.40;
    } else if mod7 <= 3 {
        score -= base * 0.25;
    } else {
        score += base * 0.15;
    }

    // ---------- 10. Dead‑space ratio ----------
    let used = old_res - new_res;
    if used > 0.0 {
        let consume_ratio = used / old_res;
        if consume_ratio > 0.85 {
            score -= base * 0.20;
        } else if consume_ratio < 0.20 {
            score += base * 0.08;
        }
    }

    // ---------- 11. Future‑fit bonus ----------
    if next_item_size > 0 && next_item_size <= new_res as u32 {
        score -= base * 0.07;
    }

    score
}

pub fn score_bin(
