    fitting_bins_count: usize,
) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    // Primary penalty scale – tuned to bin size
    let penalty_base = capacity / 18.0; // roughly 5.5 for C=100

    // 1. Residual shape: quadratic penalty for large leftovers, reward for tight fits
    let residual_ratio = post / capacity;
    let mut score = penalty_base * (1.0 - residual_ratio.powi(2)); // larger when residual small

    // 2. Next‑item lookahead: heavy penalty if the next item cannot fit
    if next_item_size > 0 {
        if next_item_size > post {
            // diff grows super‑linearly to discourage poor fits
            let diff = (next_item_size - post_residual) as f64;
            score += diff.powf(1.5) * (penalty_base / 80.0);
        } else {
            // Fits next item – bonus for tighter packing
            score -= penalty_base / 40.0;
        }
    }

    // 3. Progress‑dependent adjustment: near the end we prefer to close bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        // Late phase – penalize any residual above 10% of capacity
        if post > capacity * 0.1 {
            score += (post - capacity * 0.1) * (penalty_base / capacity);
        }
    }

    // 4. Mean residual comparison – avoid bins worse than average
    if bin_residual as f64 > mean_residual {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * (penalty_base / capacity);
    }

    // 5. Open‑bins penalty – encourage closure of many open bins
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * (penalty_base / 12.0);
    }

    // 6. Unique‑fit reward – if this is the sole fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= penalty_base * 1.8;
    }

    // 7. New‑bin candidate handling – treat empty bin specially
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Existing bin available – discourage opening a new one
            score += penalty_base * 4.5;
        } else {
            // No fit – reward opening a new bin
            score -= penalty_base * 3.2;
        }
    }

    // 8. Non‑linear residual tweak: favor residuals that are multiples of 5
    let mod5 = post_residual % 5;
    if mod5 == 0 {
        score -= penalty_base * 0.6; // small extra bonus
    } else if mod5 <= 2 {
        score -= penalty_base * 0.4;
    } else {
        score += penalty_base * 0.2;
    }

    score
}

