        }
    }

    // Future‑fit bonus – reward if next item fits into remaining space
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= base * 0.05;
    }

    // Late‑phase open‑bin check – discourage opening bins when few items remain
    if progress > 0.8 && open_bins_count > (total_items - step_index) / 20 {
        score += base * 0.2;
    }

    // Additional open‑bin efficiency check – penalise too many open bins relative to remaining items
    let remaining_items = total_items - step_index;
    if remaining_items > 0
        && open_bins_count as f64 > (remaining_items as f64) * 0.08
    {
        score += base * 0.1;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the post‑residual space (lower is better)
    let mut score = post_residual as f64;

    // Dead‑space avoidance: heavily penalise leaving a gap that can’t accommodate even the smallest
    // future item or the next item in the stream.
    if post_residual < 10 {
        score += 100.0; // impossible to fit anything
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0; // will miss the next item
    }

    // New‑bin preference: if this is an empty bin and there are already open bins,
    // favour opening a new bin only when the residual would be large.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        if post_residual < 20 {
            score += 30.0; // small residual – better to use an existing bin
        }
    }

    // Open‑bin pressure: if many bins are open, avoid creating a new tiny hole.
    if open_bins_count > 5 && post_residual < 20 {
        score += 20.0;
    }

    // Last‑chance fit: if this is the only bin that can take the item, reward using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Progress‑based tightening: when the stream is almost finished, penalise any leftover space.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus: zero residual is ideal.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Mean residual alignment: avoid leaving a gap that is significantly larger than the average.
    let bin_cap_f = bin_capacity as f64;
    let residual_pct = post_residual as f64 / bin_cap_f;
    let mean_pct = mean_residual / bin_cap_f;
    if residual_pct > mean_pct + 0.2 {
        score += (residual_pct - mean_pct) * 50.0;
    }

    score
}
